<script setup lang="ts">
import type { DraftRule, Operator } from './model'
import { operators, predicate, values } from './model'
const props = defineProps<{ rule: DraftRule }>()
function setExpression(event: Event) {
  const value = (event.target as HTMLSelectElement).value
  if (value === 'advisory_only') { props.rule.expressivity = 'advisory_only'; props.rule.predicate = null; props.rule.enforcement = 'advisory' }
  else { props.rule.expressivity = 'deterministic'; props.rule.predicate = [predicate('op_in')]; props.rule.enforcement = 'runtime' }
}
function changeOp(index: number, event: Event) {
  const value = (event.target as HTMLSelectElement).value as Operator
  if (props.rule.predicate && operators.includes(value)) props.rule.predicate[index] = predicate(value)
}
</script>
<template><div class="panel min-w-0"><div class="panel-header"><div><h2 class="panel-title">规则字段</h2><p class="panel-kicker">所有字段均属于候选草稿</p></div></div><div class="panel-body space-y-5 text-xs">
<div class="grid gap-3 sm:grid-cols-3"><label class="field"><span class="field-label">规则 ID</span><input v-model="rule.id" class="control" /></label><label class="field"><span class="field-label">维度</span><input v-model="rule.dimension" class="control" /></label><label class="field"><span class="field-label">层级</span><input v-model.number="rule.level" type="number" min="0" step="1" class="control" /></label></div>
<div class="grid gap-3 sm:grid-cols-3"><label class="field"><span class="field-label">表达力</span><select :value="rule.expressivity" class="control" @change="setExpression"><option value="deterministic">deterministic</option><option value="advisory_only">advisory_only</option></select></label><label class="field"><span class="field-label">分类</span><select v-model="rule.policy_class" class="control"><option>security</option><option>engineering</option></select></label><label class="field"><span class="field-label">执行面</span><select v-model="rule.enforcement" class="control"><option v-if="rule.expressivity === 'advisory_only'">advisory</option><template v-else><option>runtime</option><option>ci</option><option>server</option></template></select></label></div>
<div class="grid gap-3 sm:grid-cols-4"><label class="field"><span class="field-label">命中裁决</span><select v-model="rule.on_hit" class="control"><option>deny</option><option>confirm</option><option>log</option></select></label><label class="field"><span class="field-label">范围</span><select v-model="rule.scope" class="control"><option>project</option><option>session</option></select></label><label class="field"><span class="field-label">属主</span><select v-model="rule.owner" class="control"><option>human</option><option>agent</option></select></label><label class="field"><span class="field-label">TTL（留空为无）</span><input :value="rule.ttl ?? ''" placeholder="YYYY-MM-DD 或 ISO" class="control" @input="rule.ttl = ($event.target as HTMLInputElement).value || null" /></label></div>
<label class="field"><span class="field-label">说明 narrative</span><textarea v-model="rule.narrative" rows="3" class="control" /></label>
<fieldset class="space-y-3 rounded-md border border-border p-3"><legend class="px-1 font-semibold">命中条件 predicate</legend><p class="text-muted-foreground">仅支持七个固定操作符。${SESSION_WORKSPACE} 仅适用于两个 glob 模式。</p><p v-if="rule.expressivity === 'advisory_only'" class="text-muted-foreground">仅建议规则的 predicate 固定为 null。</p><template v-else><div v-for="(p, i) in rule.predicate" :key="i" class="space-y-2 rounded-md border border-border p-3"><div class="flex flex-wrap items-center gap-2"><label class="field flex-1"><span class="field-label">操作符</span><select :value="p.op" class="control" @change="changeOp(i, $event)"><option v-for="op in operators" :key="op">{{ op }}</option></select></label><button type="button" class="mt-4 rounded border border-border px-2 py-1 hover:bg-accent" @click="rule.predicate?.splice(i, 1)">删除条件</button></div><p class="text-muted-foreground">{{ Object.keys(p.args)[0] }}</p><div v-for="(_, j) in values(p)" :key="j" class="flex gap-2"><input v-model="values(p)[j]" :aria-label="`条件 ${i + 1} 参数 ${j + 1}`" class="control min-w-0 flex-1" /><button type="button" class="rounded border border-border px-2 hover:bg-accent" @click="values(p).splice(j, 1)">删除项</button></div><button type="button" class="rounded border border-border px-2 py-1 hover:bg-accent" @click="values(p).push('')">添加项</button></div><button type="button" class="rounded border border-border px-2 py-1 hover:bg-accent" @click="rule.predicate?.push(predicate('op_in'))">添加条件</button></template></fieldset>
<fieldset class="grid gap-3 rounded-md border border-border p-3 sm:grid-cols-2"><legend class="px-1 font-semibold">来源 source</legend><label v-for="key in (['repo', 'rev', 'path', 'section', 'lines', 'quote'] as const)" :key="key" class="field"><span class="field-label">{{ key }}</span><textarea v-if="key === 'quote'" v-model="rule.source[key]" rows="3" class="control" /><input v-else v-model="rule.source[key]" class="control" /></label></fieldset><label class="field"><span class="field-label">探测 probe</span><textarea v-model="rule.probe" rows="3" class="control" /></label>
</div></div></template>
<style scoped>.control { width: 100%; border: 1px solid hsl(var(--input)); border-radius: 6px; background: hsl(var(--background)); padding: 7px 9px; color: hsl(var(--foreground)); }</style>
